-- 3. È?çÁΩÆÔøΩ?----------------------------------------------------
-- agent_func_status   ‰ª£Áê?Â??Ë?ΩÂº?ÔøΩ?  1=Âº?ÔøΩ?0=Â?≥È?≠
-- agent_apply_status  ‰ª£Áê?Á?≥ËØ∑Âº?ÔøΩ?  1=Âº?Ê?æÁ?≥ÔøΩ?0=‰ª?Âê?Âè∞ËÆæÔøΩ?-- agent_credit_timing Áª?ÁÆ?Ê?∂Ê?∫       1=ËÆ¢Âç?‰ª?Ê¨æÊ?êÂ?? 2=ËÆ¢Âç?ÂÆ?Ê?ê
INSERT INTO `eb_system_config` (`name`, `title`, `form_id`, `value`, `status`)
SELECT t.name, t.title, 0, t.value, 0 FROM (
  SELECT 'agent_func_status'   AS name, 'Â?∫Â??‰ª£Áê?Â??Ë?ΩÂº?ÔøΩ? AS title, '1' AS value
  UNION ALL SELECT 'agent_apply_status',   'Â?∫Â??‰ª£Áê?Á?≥ËØ∑Âº?ÔøΩ?, '1'
  UNION ALL SELECT 'agent_credit_timing',  'Â?∫Â??‰ª£Áê?Áª?ÁÆ?Ê?∂Ê?∫', '1'
) t
WHERE NOT EXISTS (SELECT 1 FROM `eb_system_config` c WHERE c.name = t.name);

-- 4. Âê?Âè∞Ëè?Âç? --------------------------------------------------
-- 4.1 È°∂Á∫ßÁ?ÆÂΩ?„??‰ª£Áê?ÔøΩ?INSERT INTO `eb_system_menu` (`pid`, `name`, `icon`, `perms`, `component`, `menu_type`, `sort`, `is_show`)
SELECT 0, '‰ª£Áê?', 'clipboard', '', '/daili', 'M', 96, 1
WHERE NOT EXISTS (SELECT 1 FROM `eb_system_menu` WHERE `pid`=0 AND `component`='/daili' AND `menu_type`='M');

-- 4.2 ‰∏?‰∏™È°µÈù¢Ëè?Âç?
INSERT INTO `eb_system_menu` (`pid`, `name`, `icon`, `perms`, `component`, `menu_type`, `sort`, `is_show`)
SELECT m.id, t.name, '', t.perms, t.component, 'C', t.sort, 1
FROM `eb_system_menu` m
JOIN (
  SELECT '‰ª£Áê?ÁÆ°Áê?' AS name, 'admin:agent:list'        AS perms, '/daili/agentList'   AS component, 1 AS sort
  UNION ALL SELECT '‰ª£Áê?Â•?Â?±Ê??Áª?', 'admin:agent:reward:list',  '/daili/agentReward', 2
  UNION ALL SELECT '‰ª£Áê?ËÆæÁΩÆ',     'admin:agent:setting:list', '/daili/agentSetting', 3
) t
WHERE m.component='/daili' AND m.menu_type='M'
  AND NOT EXISTS (SELECT 1 FROM `eb_system_menu` x WHERE x.component = t.component AND x.menu_type='C');

-- 4.3 Ê??È?ÆÊù?È?êÔº?Ê??Â?®ÂØπÂ∫?È°µÈù¢‰∏?ÔøΩ?INSERT INTO `eb_system_menu` (`pid`, `name`, `icon`, `perms`, `component`, `menu_type`, `sort`, `is_show`)
SELECT p.id, t.name, '', t.perms, '', 'A', t.sort, 0
FROM `eb_system_menu` p
JOIN (
  SELECT '‰ª£Áê?ÁÆ°Áê?' AS page, 'Ê∑ªÂ?†‰ª£Áê?' AS name, 'admin:agent:save'    AS perms, 1 AS sort
  UNION ALL SELECT '‰ª£Áê?ÁÆ°Áê?', '‰øÆÊ?π‰ª£Áê?',   'admin:agent:update', 2
  UNION ALL SELECT '‰ª£Áê?ÁÆ°Áê?', 'ÂÆ°Ê†∏‰ª£Áê?',   'admin:agent:audit',  3
  UNION ALL SELECT '‰ª£Áê?ÁÆ°Áê?', 'Â?†È?§‰ª£Áê?',   'admin:agent:delete', 4
  UNION ALL SELECT '‰ª£Áê?ÁÆ°Áê?', 'Á?ÅÂ∏?Â?∫Ê?∞ÔøΩ?, 'admin:system:city:list:tree', 5
  UNION ALL SELECT '‰ª£Áê?ËÆæÁΩÆ', '‰øùÂ≠?ËÆæÁΩÆ',   'admin:agent:setting:save', 1
) t
JOIN `eb_system_menu` c ON c.component = CASE t.page
    WHEN '‰ª£Áê?ÁÆ°Áê?' THEN '/daili/agentList'
    WHEN '‰ª£Áê?ËÆæÁΩÆ' THEN '/daili/agentSetting' END
  AND c.menu_type='C'
WHERE p.id = c.id
  AND NOT EXISTS (SELECT 1 FROM `eb_system_menu` x WHERE x.perms = t.perms AND x.menu_type='A');

