-- 12. È?çÁΩÆÔøΩ?---------------------------------------------------
-- stock_order_audit        ËÆ¢Âç?‰∏?Á∫ßÂÆ°Ê†∏Âº?ÔøΩ?  1=Âø?È°ª‰∏?Á∫ßÂÆ°Ê†∏ 0=Á?¥Ê?•ÊµÅËΩ¨Ê?ªÈ?®
-- stock_diff_reward_status Â∑Æ‰ª∑Â•?Â?±Âº?ÔøΩ?      1=Âº?ÔøΩ?0=Â?≥È?≠
-- stock_exchange_diff      Êç¢Ë¥ßÂç?Âè?‰∏?Â∑Æ‰ª∑Â•?ÔøΩ?1=Âè?‰∏? 0=‰∏çÂè?ÔøΩ?-- stock_ladder_status      Á∫ßÂ∑ÆÂ•?Â?±Âº?ÔøΩ?      1=Âº?ÔøΩ?0=Â?≥È?≠
-- stock_ladder_cycle       Á∫ßÂ∑ÆÁª?ÁÆ?Â?®Ê??       1=Ê??ËÆ¢Âç?Áª?ÔøΩ?2=Ê??Ê??Áª?ËÆ°Áª?ÁÆ?
-- stock_peer_status        Âπ≥Á∫ßÂ•?Â?±Âº?ÔøΩ?      1=Âº?ÔøΩ?0=Â?≥È?≠
-- stock_peer_rate          Âπ≥Á∫ßÂ•?Â?±ÊØ?‰æ?ÔøΩ?ÔøΩ? Èª?ËÆ§5
-- stock_peer_generations   Âπ≥Á∫ßÂ•?Â?±‰ª£Ê?∞       Èª?ËÆ§1Ôº?Âè™Ê?øÁ?¥Ê?•Âπ≥Ê?®Âê?Á∫ßÔº?
INSERT INTO `eb_system_config` (`name`, `title`, `form_id`, `value`, `status`)
SELECT t.name, t.title, 0, t.value, 0 FROM (
  SELECT 'stock_order_audit'       AS name, 'ËÆ¢Ë¥ßËÆ¢Âç?‰∏?Á∫ßÂÆ°Ê†∏Âº?ÔøΩ? AS title, '1' AS value
  UNION ALL SELECT 'stock_diff_reward_status', 'ËÆ¢Ë¥ßÂ∑Æ‰ª∑Â•?Â?±Âº?ÔøΩ?, '1'
  UNION ALL SELECT 'stock_exchange_diff',      'Êç¢Ë¥ßÂç?Âè?‰∏?Â∑Æ‰ª∑Â•?ÔøΩ?, '0'
  UNION ALL SELECT 'stock_ladder_status',      'ËÆ¢Ë¥ßÁ∫ßÂ∑ÆÂ•?Â?±Âº?ÔøΩ?, '1'
  UNION ALL SELECT 'stock_ladder_cycle',       'ËÆ¢Ë¥ßÁ∫ßÂ∑ÆÁª?ÁÆ?Â?®Ê??', '1'
  UNION ALL SELECT 'stock_peer_status',        'ËÆ¢Ë¥ßÂπ≥Á∫ßÂ•?Â?±Âº?ÔøΩ?, '1'
  UNION ALL SELECT 'stock_peer_rate',          'ËÆ¢Ë¥ßÂπ≥Á∫ßÂ•?Â?±ÊØ?‰æ?', '5'
  UNION ALL SELECT 'stock_peer_generations',   'ËÆ¢Ë¥ßÂπ≥Á∫ßÂ•?Â?±‰ª£Ê?∞', '1'
) t
WHERE NOT EXISTS (SELECT 1 FROM `eb_system_config` c WHERE c.name = t.name);

-- 13. Âê?Âè∞Ëè?Âç? -------------------------------------------------
-- 13.1 È°∂Á∫ßÁ?ÆÂΩ?„??ËÆ¢Ë¥ßÔøΩ?INSERT INTO `eb_system_menu` (`pid`, `name`, `icon`, `perms`, `component`, `menu_type`, `sort`, `is_show`)
SELECT 0, 'ËÆ¢Ë¥ß', 'shopping-cart', '', '/stock', 'M', 95, 1
WHERE NOT EXISTS (SELECT 1 FROM `eb_system_menu` WHERE `pid`=0 AND `component`='/stock' AND `menu_type`='M');

-- 13.2 È°µÈù¢Ëè?Âç?
INSERT INTO `eb_system_menu` (`pid`, `name`, `icon`, `perms`, `component`, `menu_type`, `sort`, `is_show`)
SELECT m.id, t.name, '', t.perms, t.component, 'C', t.sort, 1
FROM `eb_system_menu` m
JOIN (
  SELECT 'ËÆ¢Ë¥ß‰ª£Áê?' AS name, 'admin:stock:agent:list'      AS perms, '/stock/agent'    AS component, 1 AS sort
  UNION ALL SELECT 'Â??Â?Å‰∏?Â∫?ÔøΩ?, 'admin:stock:product:list', '/stock/product', 2
  UNION ALL SELECT 'ËÆ¢Ë¥ßËÆ¢Âç?',   'admin:stock:order:list',   '/stock/order',   3
  UNION ALL SELECT 'Êç¢Ë¥ßÁÆ°Áê?',   'admin:stock:exchange:list','/stock/exchange',4
  UNION ALL SELECT 'Â•?È??Ê??Áª?',   'admin:stock:reward:list',  '/stock/reward',  5
  UNION ALL SELECT 'Â•?Â?±Ëß?Â??',   'admin:stock:setting:list', '/stock/setting', 6
  UNION ALL SELECT 'Ê?∞ÊçÆÊ?•Ë°®',   'admin:stock:report:list',  '/stock/report',  7
) t
WHERE m.component='/stock' AND m.menu_type='M'
  AND NOT EXISTS (SELECT 1 FROM `eb_system_menu` x WHERE x.component = t.component AND x.menu_type='C');

-- 13.3 Ê??È?ÆÊù?È?ê
INSERT INTO `eb_system_menu` (`pid`, `name`, `icon`, `perms`, `component`, `menu_type`, `sort`, `is_show`)
SELECT p.id, t.name, '', t.perms, '', 'A', t.sort, 0
FROM `eb_system_menu` p
JOIN (
  SELECT 'ËÆ¢Ë¥ß‰ª£Áê?' AS page, 'Ê?∞Â¢?‰ª£Áê?' AS name, 'admin:stock:agent:save'      AS perms, 1 AS sort
  UNION ALL SELECT 'ËÆ¢Ë¥ß‰ª£Áê?', '‰øÆÊ?π‰ª£Áê?',   'admin:stock:agent:update',    2
  UNION ALL SELECT 'ËÆ¢Ë¥ß‰ª£Áê?', 'Â?†È?§‰ª£Áê?',   'admin:stock:agent:delete',    3
  UNION ALL SELECT 'Â??Â?Å‰∏?Â∫?ÔøΩ?, 'ËÆæÁΩÆÊ?øË¥ßÔøΩ?, 'admin:stock:price:save',    1
  UNION ALL SELECT 'Â??Â?Å‰∏?Â∫?ÔøΩ?, 'Ë∞?Ê?¥Â∫?Â≠?',   'admin:stock:log:adjust',    2
  UNION ALL SELECT 'ËÆ¢Ë¥ßËÆ¢Âç?', 'ÂÆ°Ê†∏ËÆ¢Âç?',   'admin:stock:order:audit',     1
  UNION ALL SELECT 'ËÆ¢Ë¥ßËÆ¢Âç?', 'Á°ÆËÆ§Ê?∂Ê¨æ',   'admin:stock:order:pay',       2
  UNION ALL SELECT 'ËÆ¢Ë¥ßËÆ¢Âç?', 'ËÆ¢Âç?Âè?Ë¥ß',   'admin:stock:order:send',      3
  UNION ALL SELECT 'Êç¢Ë¥ßÁÆ°Áê?', 'Êç¢Ë¥ßÂÆ°Ê†∏',   'admin:stock:exchange:audit',  1
  UNION ALL SELECT 'Êç¢Ë¥ßÁÆ°Áê?', 'Êç¢Ë¥ßÂ?•Â∫?',   'admin:stock:exchange:back',   2
  UNION ALL SELECT 'Êç¢Ë¥ßÁÆ°Áê?', 'Êç¢Ë¥ßÂè?Ë¥ß',   'admin:stock:exchange:send',   3
  UNION ALL SELECT 'Â•?Â?±Ëß?Â??', '‰øùÂ≠?Ëß?Â??',   'admin:stock:setting:save',    1
  UNION ALL SELECT 'Ê?∞ÊçÆÊ?•Ë°®', 'ÂØºÂ?∫Ê?•Ë°®',   'admin:stock:report:export',   1
) t
JOIN `eb_system_menu` c ON c.component = CASE t.page
    WHEN 'ËÆ¢Ë¥ß‰ª£Áê?' THEN '/stock/agent'
    WHEN 'Â??Â?Å‰∏?Â∫?ÔøΩ? THEN '/stock/product'
    WHEN 'ËÆ¢Ë¥ßËÆ¢Âç?' THEN '/stock/order'
    WHEN 'Êç¢Ë¥ßÁÆ°Áê?' THEN '/stock/exchange'
    WHEN 'Â•?Â?±Ëß?Â??' THEN '/stock/setting'
    WHEN 'Ê?∞ÊçÆÊ?•Ë°®' THEN '/stock/report' END
  AND c.menu_type='C'
WHERE p.id = c.id
  AND NOT EXISTS (SELECT 1 FROM `eb_system_menu` x WHERE x.perms = t.perms AND x.menu_type='A');

