-- ========== BEGIN: stock_adjust_log_link_uid.sql ==========
-- ËÆ¢Ë¥ßÁ≥ªÁª?-Ë??Ê??Â∫?Â≠?ËΩ¨Âç?Ê∫ØÊ∫êÔº?Â∫?Â≠?Ë∞?Ê?¥ÊµÅÊ∞¥Ë°•ËÆ∞„??È??Ë¥≠‰∫∫„?çÔº?‰∏?Âç?Á??‰∏?Á∫ß‰º?Â??UIDÔøΩ?--
-- Ë??Ê?ØÔº?‰∏?Á∫ßÈ??Ë¥≠‰∏?Á∫ßÁ??Ë??Ê??Â∫?Â≠?Ê?∂Ôº?‰∏?Á∫ßË??Ê??Â∫?Â≠?‰º?Á≠?È?èÊ?£Â?èÔº?‰Ω?Ë∞?Ê?¥ÊµÅÊ∞¥Ê≠§Â?çÂè™ËÆ∞‰∫?‰∏?Á∫ßË?™Â∑±ÔøΩ?--       uidÔº?‰∏?Á∫ßÂ?®‰º?Â??Á´Ø„??Â∫?Â≠?ËÆ∞ÂΩ?„?çÈ??Á??‰∏çÂ?∞Ê?ØË∞Å‰π∞Á??„??Ê≠§Ë°•‰∏ÅË°•Â?? + Ê??Â§?Ê≥®‰∏≠Á??ËÆ¢Âç?Âè∑Â??Â°´Â??Âè≤ÊµÅÊ∞¥ÔøΩ?-- Âπ?Á≠?Ôº?Â??ÔøΩ?information_schema Â?§Ê?≠Â??Ê?ØÂê¶Â≠?Â?®Ôº?‰∏çÂ≠?Â?®Ê?ç ALTERÔº?Â??Â°´Âè™Ê?¥Ê?∞ link_uid=0 Á??Ë°?ÔøΩ?-- ============================================================
SET @db = DATABASE();

SET @s = IF(
    (SELECT COUNT(*) FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA=@db AND TABLE_NAME='eb_stock_adjust_log' AND COLUMN_NAME='link_uid') = 0,
    'ALTER TABLE `eb_stock_adjust_log` ADD COLUMN `link_uid` int NOT NULL DEFAULT 0 COMMENT ''Â?≥ËÅ?‰∏?Á∫ßUIDÔº?Ë??Ê??Â∫?Â≠?ËΩ¨Âç?Á??È??Ë¥≠‰∫∫Ôº?‰∏?Âç?‰º?Â??UIDÔº?Ôº?0=ÔøΩ?' AFTER `mark`',
    'SELECT 1');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- Â??Âè≤ÊµÅÊ∞¥Â??Â°´Ôº?Â§?Ê≥®ÂΩ¢Â¶?„??Ë??Ê??Â∫?Â≠?ËΩ¨Âç?Áª?‰∏?Á∫ßÔº?ËÆ¢ÔøΩ?SK17898828422122548Ôº?Ôº?Ê?¨Ê¨°Ê?£Â?è 2ÔøΩ?-- ‰ª?ÂΩ? eb_stock_order Â≠?Â?®Ê?∂Ê?ßË°?Ôº?Ê≠£Â∏∏È?®ÁΩ≤È°∫Â∫è‰∏?Âù?Â≠?Â?®ÔøΩ?SET @s = IF(
    (SELECT COUNT(*) FROM information_schema.TABLES
      WHERE TABLE_SCHEMA=@db AND TABLE_NAME='eb_stock_order') > 0,
    'UPDATE `eb_stock_adjust_log` l JOIN `eb_stock_order` o ON l.`mark` LIKE CONCAT(''%'', o.`order_no`, ''%'') SET l.`link_uid` = o.`uid` WHERE l.`stock_type` = 2 AND l.`num` < 0 AND (l.`link_uid` IS NULL OR l.`link_uid` = 0)',
    'SELECT 1');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- ========== END: stock_adjust_log_link_uid.sql ==========

