-- ËÆ¢Ë¥ßÁ≥ªÁª?-Êç¢Ë¥ßÊµÅÁ®?Â¢?Âº∫Ôº?Êç¢Â?•Â∫?Â≠?Á±ªÔøΩ?--
-- Ë??Ê?ØÔº?Ë??Ê??Â∫?Â≠?Êç¢Ë¥ßÊ?∂‰º?Â??ÂèØÈ??Ê?©„??Êç¢ÂÆ?‰Ω? / Êç¢Ë??Ê??„?çÔº?
--       Êç¢Ë??ÔøΩ?ÔøΩ?‰∏?Á∫ßÂÆ°Ê†∏È??Ëø?Âê?Á?¥Ê?•Ê?£‰∏?Á∫ßË??Ê??Â∫?Â≠?Âπ∂Â?•Ë¥¶Áª?Á?≥ËØ∑‰∫∫Ôº?Ê?†È??Â?∞Âù?„?ÅÊ?†È??Âè?Ë¥ßÔº?Ôº?
--       Êç¢ÂÆ?ÔøΩ?ÔøΩ?È??Ë¶ÅÊ?∂Ë¥ßÂ?∞Âù?Ôº?Ëµ∞Âè?Ê?∞Â?ÅÊµÅÁ®?Ôº?ÂÆ?Ê?êÂê?Ê?£Â?è‰∏?Á∫ßÂÆ?‰Ω?ÂèØ‰æ?Â∫?È?èÔøΩ?--       NULL/1 Ëß?‰∏∫ÂÆ?‰Ω?Ôº?Â?ºÂÆπÂ??Âè≤Ê?∞ÊçÆÔº?Â??Âè≤Êç¢Ë¥ßÂç?Âù?Ê??ÂÆ?‰Ω?Âè?Ë¥ßÂ§?Áê?Ôº?ÔøΩ?-- Âπ?Á≠?Ôº?Â??ÔøΩ?information_schema Â?§Ê?≠Â??Ê?ØÂê¶Â≠?Â?®Ôº?‰∏çÂ≠?Â?®Ê?ç ALTERÔøΩ?-- ============================================================
SET @db = DATABASE();

SET @s = IF(
    (SELECT COUNT(*) FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA=@db AND TABLE_NAME='eb_stock_exchange' AND COLUMN_NAME='target_stock_type') = 0,
    'ALTER TABLE `eb_stock_exchange` ADD COLUMN `target_stock_type` tinyint NULL DEFAULT 1 COMMENT ''Êç¢Â?•Â∫?Â≠?Á±ªÂ??ÔøΩ?=ÂÆ?‰Ω? 2=Ë??Ê??Ôº?Ë??Ê??Êç¢Ë¥ßÊ?∂‰º?Â??ÂèØÈ??Ôº?Ôº?NULL/1=ÂÆ?‰Ω?'' AFTER `target_sku_key`',
    'SELECT 1');
