-- ========== BEGIN: fix_virtual_in_log_20260921.sql ==========
-- Ë°•Â??Âè≤„??Ë??Ê??Â∫?Â≠?Â?•Ë¥¶„?çÊµÅÊ∞¥Ôº?Ë??Ê??È??Ë¥≠Âç?Â?•Ë¥¶Ê≠§Â?ç‰∏çÔøΩ?eb_stock_adjust_logÔøΩ?-- ‰º?Â??Á´Ø„??Â∫?Â≠?ËÆ∞ÔøΩ?Ë??Ê??Â∫?Â≠?„?çÂè™Ê??ÊèêÔøΩ?ËΩ¨Âç?Â?∫Â∫?„?ÅÁ??‰∏çÂ?∞È??Ë¥≠Â?•Â∫?„??‰ª£Á†ÅÂ∑≤‰øÆÔº?Ëø?È??Ë°•Â??Âè≤Âç?ÔøΩ?-- Âπ?Á≠?Ôº?Âê?ËÆ¢Âç?Â∑≤Ê??Â?•Ë¥¶ÊµÅÊ∞¥Ôº?stock_type=2 ÔøΩ?num>0 ÔøΩ?mark Âê´Âç?Âè∑Ôº?Â??Ë∑≥Ëø?Ôº?ÂèØÈ?çÂ§çÊ?ßË°?ÔøΩ?INSERT INTO eb_stock_adjust_log
    (agent_id, uid, link_uid, product_id, sku_key, stock_type, num, mark, is_del, create_time)
SELECT * FROM (
    SELECT o.agent_id,
           o.uid,
           0 AS link_uid,
           p.product_id,
           IFNULL(p.sku_key, '') AS sku_key,
           2 AS stock_type,
           p.num,
           CONCAT('Ë??Ê??Â∫?Â≠?Â?•Ë¥¶Ôº?ËÆ¢ÔøΩ?', o.order_no, 'Ôº?Ôº?Ê?¨Ê¨°Â¢?Â?† ', p.num) AS mark,
           0 AS is_del,
           o.create_time
      FROM eb_stock_order o
      JOIN eb_stock_order_product p ON p.order_id = o.id
     WHERE o.is_del = 0
       AND o.order_type = 1
       AND o.stock_type = 2
       AND o.status = 4
       AND p.num > 0
       AND NOT EXISTS (
             SELECT 1 FROM eb_stock_adjust_log a
              WHERE a.agent_id = o.agent_id
                AND a.stock_type = 2
                AND a.num > 0
                AND a.is_del = 0
                AND a.mark LIKE CONCAT('%', o.order_no, '%')
           )
) t;
-- ========== END: fix_virtual_in_log_20260921.sql ==========

